package com.blockblastai; import java.util.*; public class SolverSmokeTest {public static void main(String[] a){Solver.Shape s=new Solver.Shape(new int[]{0},new int[]{0}); Solver.Move m=Solver.solve(127L,List.of(s)); if(m==null||m.x!=7||m.y!=0||m.board!=0)throw new AssertionError(); if(Solver.solve(-1L,List.of(s))!=null)throw new AssertionError(); m=Solver.solve(0,List.of(s,s,s));if(m==null||Long.bitCount(m.board)!=1)throw new AssertionError();System.out.println("3 tests passed");}}
